import { closeSync, existsSync, openSync, readdirSync, readFileSync, readSync } from "node:fs";
import { join, posix } from "node:path";

/** Starts the first line of every generated file (after `// ` or `<!-- `). */
export const GENERATED = "Generated by scripts/modules.ts";

/** Whether the generator wrote `file`: its first line says so. */
export function isGenerated(file: string) {
	const buffer = Buffer.alloc(64);
	const fd = openSync(file, "r");
	try {
		const text = buffer.toString("utf8", 0, readSync(fd, buffer));
		return text.startsWith(`// ${GENERATED}`) || text.startsWith(`<!-- ${GENERATED}`);
	} finally {
		closeSync(fd);
	}
}

/**
 * Whether `dir` is a stub folder of the generator's earlier versions, which wrote a module's route
 * folder beside the core's (`src/routes/(app)/contracts`) with a `.gitignore` that ignored it.
 */
export function isLegacyStubFolder(dir: string) {
	const file = join(dir, ".gitignore");
	return existsSync(file) && readFileSync(file, "utf8").startsWith(`# ${GENERATED}`);
}

/** What a module's folder contains that the generator needs to know about. */
export interface ModuleFolder {
	/** The folder's name. */
	id: string;
	/** The `id:` that `module.ts` states, if it states one as a string, to check against the folder. */
	declaredId?: string;
	/** Whether `module.ts` has a `portal:` entry (its label and icon in the portal's navigation). */
	declaresPortal?: boolean;
	/**
	 * The keys of `module.ts` that name a page of the module's (`route:`, `settings:`), which come
	 * from where its `routes/` has them instead (`modulePages()`).
	 */
	declaredPages?: string[];
	/** The ids in `requires` of `module.ts`: modules that must be on for this one to be. */
	requires: string[];
	/** The ids in `enhances`: modules this one adds to when they're on, but doesn't need. */
	enhances: string[];
	/** Whether `module.ts` says `alwaysOn: true`. */
	alwaysOn: boolean;
	/** What its sidebar entry goes after (`nav: { after }`): a core entry's id or a module's. */
	navAfter: string | null;
	/** Its `+` route files, relative to `routes/`, with `/`, sorted. */
	routeFiles: string[];
	/**
	 * Its components at extension points' slots, relative to its folder, with `/`, sorted:
	 * `slots/<point id>/<name>.svelte`.
	 */
	slotFiles: string[];
	/** Its bulk actions for tables, likewise: `bulk-actions/<point id>.ts`. */
	bulkFiles: string[];
	/**
	 * Its columns for lists, likewise, in two halves: the definitions (`columns/<point id>.ts`) and
	 * their SQL (`server/columns/<point id>.ts`).
	 */
	columnFiles: string[];
	serverColumnFiles: string[];
	/**
	 * The schemas of its parts of forms (`form-parts/<point id>.ts`), which go with its components
	 * at those form slots.
	 */
	formPartFiles: string[];
	/**
	 * What its pages show while they load, one per page, mirroring `routes/`:
	 * `skeletons/(app)/page.svelte` for `routes/(app)/+page.svelte`.
	 */
	skeletonFiles: string[];
	/** Which of the server files it has. */
	server: { index: boolean; schema: boolean; seed: boolean };
	/** Its message sections (`messages/<locale>/<section>.json`) per language, sorted. */
	messages: Record<string, string[]>;
}

export const byName = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

/** The files under `dir`, relative to it, with `/`, sorted. */
export function walk(dir: string): string[] {
	if (!existsSync(dir)) return [];
	return readdirSync(dir, { recursive: true, withFileTypes: true })
		.filter((entry) => !entry.isDirectory())
		.map((entry) => posix.relative(dir.replaceAll("\\", "/"), join(entry.parentPath, entry.name)))
		.toSorted(byName);
}
